import{_ as a,H as e,f as n,i}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"13 | 动手实现一个简单的MCPClient","description":"","frontmatter":{},"headers":[{"level":2,"title":"MCP 通信方式","slug":"mcp-通信方式","link":"#mcp-通信方式","children":[]},{"level":2,"title":"Stdio 方式","slug":"stdio-方式","link":"#stdio-方式","children":[{"level":3,"title":"项目初始化","slug":"项目初始化","link":"#项目初始化","children":[]},{"level":3,"title":"设置服务器连接参数","slug":"设置服务器连接参数","link":"#设置服务器连接参数","children":[]},{"level":3,"title":"建立服务器连接","slug":"建立服务器连接","link":"#建立服务器连接","children":[]},{"level":3,"title":"调用工具","slug":"调用工具","link":"#调用工具","children":[]},{"level":3,"title":"运行客户端","slug":"运行客户端","link":"#运行客户端","children":[]}]},{"level":2,"title":"SSE 方式","slug":"sse-方式","link":"#sse-方式","children":[{"level":3,"title":"什么是 SSE？","slug":"什么是-sse","link":"#什么是-sse","children":[]},{"level":3,"title":"改造 MCP Server 代码","slug":"改造-mcp-server-代码","link":"#改造-mcp-server-代码","children":[]},{"level":3,"title":"改造 MCP Client 代码","slug":"改造-mcp-client-代码","link":"#改造-mcp-client-代码","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"DeepSeek应用开发实战/13｜动手实现一个简单的MCPClient.md","filePath":"DeepSeek应用开发实战/13｜动手实现一个简单的MCPClient.md","lastUpdated":1795486824000}'),t={name:"DeepSeek应用开发实战/13｜动手实现一个简单的MCPClient.md"};function p(l,s,o,r,c,h){return e(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="_13-动手实现一个简单的mcpclient" tabindex="-1">13 | 动手实现一个简单的MCPClient <a class="header-anchor" href="#_13-动手实现一个简单的mcpclient" aria-label="Permalink to &quot;13 | 动手实现一个简单的MCPClient&quot;">​</a></h1><p>你好，我是邢云阳。</p><p>上节课，我带你动手实现了一个 MCP Server，并使用 Roo Code 与 Claude Desktop 作为MCP 客户端测试了功能。这节课，我们将进一步学习如何使用 MCP Python SDK 来编写一个MCP Client，以便更加灵活地与 MCP 服务器进行通信和集成。</p><h2 id="mcp-通信方式" tabindex="-1">MCP 通信方式 <a class="header-anchor" href="#mcp-通信方式" aria-label="Permalink to &quot;MCP 通信方式&quot;">​</a></h2><p>在写代码之前，我们需要先了解一下 MCP 支持的两种通信方式：</p><ul><li><p>标准输入输出（Standard Input/Output, stdio）：客户端通过启动服务器子进程并使用标准输入（stdin）和标准输出（stdout）建立双向通信，一个服务器进程只能与启动它的客户端通信（1:1 关系）。stdio 适用于本地快速集成的场景。</p></li><li><p>服务器发送事件（Server-Sent Events, SSE）：服务器作为独立进程运行，客户端和服务器代码完全解耦，支持多个客户端随时连接和断开。</p></li></ul><p>这节课，我们分别了解一下这两种方式。</p><h2 id="stdio-方式" tabindex="-1">Stdio 方式 <a class="header-anchor" href="#stdio-方式" aria-label="Permalink to &quot;Stdio 方式&quot;">​</a></h2><p>首先我来实现一个简单的示例，带你体会一下 stdio 方式 MCP Client 与 MCP Server 的通信过程。</p><h3 id="项目初始化" tabindex="-1">项目初始化 <a class="header-anchor" href="#项目初始化" aria-label="Permalink to &quot;项目初始化&quot;">​</a></h3><p>我们还是使用 uv 工具对项目进行初始化。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uv init mcp-client-demo</span></span>
<span class="line"><span>uv add &quot;mcp[cli]&quot;</span></span>
<span class="line"><span>pip install mcp</span></span></code></pre></div><p>初始化完成后，我们将 hello.py 删除，然后创建一个 client.py。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/13/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/13/1.png" alt=""></a></p><p>接下来，开始写代码。首先引用一下 MCP Client 的包。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mcp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ClientSession, StdioServerParameters</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mcp.client.stdio </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stdio_client</span></span></code></pre></div><h3 id="设置服务器连接参数" tabindex="-1">设置服务器连接参数 <a class="header-anchor" href="#设置服务器连接参数" aria-label="Permalink to &quot;设置服务器连接参数&quot;">​</a></h3><p>之后需要编写设置服务器连接参数的代码。在使用 stdio 方式进行通信时，MCP 服务器的进程由 MCP 客户端程序负责启动。因此，我们通过 StdioServerParameters 来配置服务器进程的启动参数，包括运行 MCP 服务器的命令及其对应的参数。代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Create server parameters for stdio connection</span></span>
<span class="line"><span>server_params = StdioServerParameters(</span></span>
<span class="line"><span>   command=&quot;uv&quot;, # Executable</span></span>
<span class="line"><span>   args=[</span></span>
<span class="line"><span>       &quot;run&quot;,</span></span>
<span class="line"><span>       &quot;--with&quot;,</span></span>
<span class="line"><span>       &quot;mcp[cli]&quot;,</span></span>
<span class="line"><span>       &quot;--with-editable&quot;,</span></span>
<span class="line"><span>       &quot;D:\\\\workspace\\\\python\\\\mcp-test\\\\achievement&quot;,</span></span>
<span class="line"><span>       &quot;mcp&quot;,</span></span>
<span class="line"><span>       &quot;run&quot;,</span></span>
<span class="line"><span>       &quot;D:\\\\workspace\\\\python\\\\mcp-test\\\\achievement\\\\server.py&quot;</span></span>
<span class="line"><span>   ],# Optional command line arguments</span></span>
<span class="line"><span>   env=None # Optional environment variables</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>代码非常简单，就是一个 command 加 args。这两部分填的内容，就是上节课我们配置 MCPServer 运行的配置文件时的内容。通过配置这部分内容，可以确保 MCP 客户端能够正确启动并连接到 MCP 服务器。</p><h3 id="建立服务器连接" tabindex="-1">建立服务器连接 <a class="header-anchor" href="#建立服务器连接" aria-label="Permalink to &quot;建立服务器连接&quot;">​</a></h3><p>接下来，我们写一个 run 方法来建立客户端与服务器的连接。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>async def run():</span></span>
<span class="line"><span>   async with stdio_client(server_params) as (read, write):</span></span>
<span class="line"><span>       async with ClientSession(read, write) as session:</span></span>
<span class="line"><span>           # Initialize the connection</span></span>
<span class="line"><span>           await session.initialize()</span></span></code></pre></div><p>stdio_client 负责启动服务器进程并建立双向通信通道，它返回用于读写数据的流对象。ClientSession 则在这些流的基础上提供高层的会话管理，包括初始化连接、维护会话状态等。代码无需深究其含义，会套路即可。</p><h3 id="调用工具" tabindex="-1">调用工具 <a class="header-anchor" href="#调用工具" aria-label="Permalink to &quot;调用工具&quot;">​</a></h3><p>接下来就是 MCP Client 的核心部分——工具的调用。工具的调用分为两个步骤，第一个步骤是列出 MCP Server 支持的工具，即 list_tools()。第二个步骤是调用指定工具，即call_tool(name, args)。 代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>async def run():</span></span>
<span class="line"><span>   async with stdio_client(server_params) as (read, write):</span></span>
<span class="line"><span>       async with ClientSession(read, write) as session:</span></span>
<span class="line"><span>           # Initialize the connection</span></span>
<span class="line"><span>           await session.initialize()</span></span>
<span class="line"><span>           # List available tools</span></span>
<span class="line"><span>           tools = await session.list_tools()</span></span>
<span class="line"><span>           print(&quot;Tools:&quot;, tools)</span></span>
<span class="line"><span>           # call a tool</span></span>
<span class="line"><span>           score = await session.call_tool(name=&quot;get_score_by_name&quot;,arguments={&quot;</span></span>
<span class="line"><span>           print(&quot;score: &quot;, score)</span></span></code></pre></div><p>由于我们是与上一节课的 MCP Server 建立的连接，因此 call_tool 的 name 参数填写上节课写的 get_score_by_name 工具，工具的参数是一个字典类型，需要写成 {“arg1”: “value”} 的形式，此处写“张三”，表示返回张三的绩效。</p><p>最后不要忘了启动 run 函数。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> __name__</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;__main__&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> asyncio</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   asyncio.run(run())</span></span></code></pre></div><h3 id="运行客户端" tabindex="-1">运行客户端 <a class="header-anchor" href="#运行客户端" aria-label="Permalink to &quot;运行客户端&quot;">​</a></h3><p>我们可以使用 uv 命令运行程序。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uv run .\\client.py</span></span></code></pre></div><p>打印信息如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[03/06/25 21:15:35] INFO     Processing request of type ListToolsRequest</span></span>
<span class="line"><span>Tools: meta=None nextCursor=None tools=[Tool(name=&#39;get_score_by_name&#39;, descriptio</span></span>
<span class="line"><span>分&#39;, inputSchema={&#39;properties&#39;: {&#39;name&#39;: {&#39;title&#39;: &#39;Name&#39;, &#39;type&#39;: &#39;string&#39;}​}, &#39;r</span></span>
<span class="line"><span>                   INFO     Processing request of type CallToolRequest</span></span>
<span class="line"><span>score:  meta=None content=[TextContent(type=&#39;text&#39;, text=&#39;name: 张三 绩效评分: 85.9</span></span></code></pre></div><p>可以看到 list_tools 列出了我们定义的 get_score_by_name 工具，而且很神奇的是我们的打印结果还包含了 inputSchema，这说明 MCP Server 自动帮我们写了 JSON 格式的参数描述。</p><p>之后我们通过 call_tools 调用了 get_score_by_name 工具，成功返回了张三的绩效。这说明我们这个手动版本的 MCP Client 与 MCP Server 成功建立了通信。</p><h2 id="sse-方式" tabindex="-1">SSE 方式 <a class="header-anchor" href="#sse-方式" aria-label="Permalink to &quot;SSE 方式&quot;">​</a></h2><p>接下来我们看一下 SSE 方式，需要首先了解一下什么是 SSE。</p><h3 id="什么是-sse" tabindex="-1">什么是 SSE？ <a class="header-anchor" href="#什么是-sse" aria-label="Permalink to &quot;什么是 SSE？&quot;">​</a></h3><p>Server-Sent Events（SSE，服务器发送事件）是一种基于 HTTP 协议的技术，允许服务器向客户端单向、实时地推送数据。在 SSE 模式下，客户端通过创建一个 EventSource 对象与服务器建立持久连接，服务器则通过该连接持续发送数据流，而无需客户端反复发送请求。MCP Python SDK 使用了 Starlette 框架来实现 SSE。</p><p>SSE 模式下客户端通过访问 Server 的 /messages 端点发送 JSON-RPC 调用，并通过 /sse端点获取服务器推送的 JSON-RPC 消息。</p><h3 id="改造-mcp-server-代码" tabindex="-1">改造 MCP Server 代码 <a class="header-anchor" href="#改造-mcp-server-代码" aria-label="Permalink to &quot;改造 MCP Server 代码&quot;">​</a></h3><p>为了能让上节课编写的 MCP Server 代码支持 SSE，我们需要对代码进行改造。改造点主要是需要实现一个 SSE 服务器。先上代码：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> create_starlette_app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mcp_server: Server, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, debug: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bool</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> False</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; Starlette</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   &quot;&quot;&quot;Create a Starlette application that can server the provied mcp server with</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   sse = SseServerTransport(&quot;/messages/&quot;)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   async def handle_sse(request: Request) -&gt; None:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       async with sse.connect_sse(</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">               request.scope,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">               request.receive,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">               request._send,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       ) as (read_stream, write_stream):</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">           await mcp_server.run(</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">               read_stream,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">               write_stream,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">               mcp_server.create_initialization_options(),</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">           )</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   return Starlette(</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       debug=debug,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       routes=[</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">           Route(&quot;/sse&quot;, endpoint=handle_sse),</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">           Mount(&quot;/messages/&quot;, app=sse.handle_post_message),</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       ],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   )</span></span></code></pre></div><p>该函数在最开始创建了 SseServerTransport 对象，并指定基础路径 /messages/，用于后续管理 SSE 连接和消息传递。</p><p>之后的 handle_sse 是一个异步请求处理函数，当客户端请求建立 SSE 连接时会被调用。在该方法中利用 sse.connect_sse 方法，传入当前请求的 scope、receive 方法和 _send 方法，建立一个异步上下文管理器。管理器会返回两个数据流，分别是 read_stream 用于读取客户端发送的数据以及 write_stream 用于向客户端发送数据。</p><p>在成功建立连接后，调用 mcp_server.run 方法，并传入读取、写入流以及由mcp_server.create_initialization_options() 生成的初始化参数。这一过程实现了 MCP 服务器与客户端之间的实时数据交互。</p><p>最后 create_starlette_app 方法返回一个新的 Starlette 应用实例，包括调试模式以及路由设置。</p><p>路由设置使用 Route(“/sse”, endpoint=handle_sse) 定义 /sse 路径，当客户端访问此路径时将触发 handle_sse 函数处理 SSE 连接。</p><p>使用 Mount(“/messages/”, app=sse.handle_post_message) 将 /messages/ 路径挂载到sse.handle_post_message 应用上，用于处理通过 POST 请求发送的消息，实现与 SSE 长连接的消息传递功能。</p><p>这样，一个 SSE 服务就实现好了。这部分代码对于 Python 新手来说有点抽象，可以先直接照抄，使用起来，等到后面对于 Python 越来越熟练了，再去理解。</p><p>另一个改造点需要创建 MCP 服务器实例，然后通过上面定义的 create_starlette_app 方法创建 Starlette 应用，最后使用 uvicorn 启动 ASGI 服务器，实现实时的 SSE 数据传输。代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>   mcp_server = mcp._mcp_server</span></span>
<span class="line"><span>   parser = argparse.ArgumentParser(description=&#39;Run MCP SSE-based server&#39;)</span></span>
<span class="line"><span>   parser.add_argument(&#39;--host&#39;, default=&#39;0.0.0.0&#39;, help=&#39;Host to bind to&#39;)</span></span>
<span class="line"><span>   parser.add_argument(&#39;--port&#39;, type=int, default=18080, help=&#39;Port to listen o</span></span>
<span class="line"><span>   args = parser.parse_args()</span></span>
<span class="line"><span>   # Bind SSE request handling to MCP server</span></span>
<span class="line"><span>   starlette_app = create_starlette_app(mcp_server, debug=True)</span></span>
<span class="line"><span>   uvicorn.run(starlette_app, host=args.host, port=args.port)</span></span></code></pre></div><p>同样是先用起来，我们的重点要放在工具如何编写上，这种套路代码，都不需要研究太深。</p><p>代码完成后，可以通过 uv 命令运行起来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uv run server.py</span></span></code></pre></div><p>效果为：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/13/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/13/2.png" alt=""></a></p><h3 id="改造-mcp-client-代码" tabindex="-1">改造 MCP Client 代码 <a class="header-anchor" href="#改造-mcp-client-代码" aria-label="Permalink to &quot;改造 MCP Client 代码&quot;">​</a></h3><p>客户端的改造会相对简单，就是使用 sse_client 替换 stdio_client，并在初始化时传入 MCPServer 的 HTTP 访问地址。代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>async def connect_to_sse_server(server_url: str):</span></span>
<span class="line"><span>   &quot;&quot;&quot;Connect to an MCP server running with SSE transport&quot;&quot;&quot;</span></span>
<span class="line"><span>   # Store the context managers so they stay alive</span></span>
<span class="line"><span>   async with sse_client(url=server_url) as (read, write):</span></span>
<span class="line"><span>       async with ClientSession(read, write) as session:</span></span>
<span class="line"><span>           await session.initialize()</span></span>
<span class="line"><span>           # List available tools to verify connection</span></span>
<span class="line"><span>           print(&quot;Initialized SSE client...&quot;)</span></span>
<span class="line"><span>           print(&quot;Listing tools...&quot;)</span></span>
<span class="line"><span>           response = await session.list_tools()</span></span>
<span class="line"><span>           tools = response.tools</span></span>
<span class="line"><span>           print(&quot;\\nConnected to server with tools:&quot;, [tool.name for tool in too</span></span>
<span class="line"><span>           # call a tool</span></span>
<span class="line"><span>           score = await session.call_tool(name=&quot;get_score_by_name&quot;,arguments={&quot;</span></span>
<span class="line"><span>           print(&quot;score: &quot;, score)</span></span></code></pre></div><p>这段代码是对原来的 run 方法进行了改造，重点在于 1～6 行，其他部分保持不变。</p><p>之后在启动时传入 URL 即可。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>async def main():</span></span>
<span class="line"><span>   if len(sys.argv) &lt; 2:</span></span>
<span class="line"><span>       print(&quot;Usage: uv run client.py &lt;​URL of SSE MCP server (i.e. http://localh</span></span>
<span class="line"><span>       sys.exit(1)</span></span>
<span class="line"><span>   await connect_to_sse_server(server_url=sys.argv[1])</span></span>
<span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>   asyncio.run(main())</span></span></code></pre></div><p>同样是使用 uv 命令运行程序：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uv run client-sse.py http://localhost:18080/sse</span></span></code></pre></div><p>效果为：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/13/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/13/3.png" alt=""></a></p><p>至此，SSE 方式就实现了。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我们学习了 MCP Client 与 Server 之间的两种通讯方法，并使用代码实操的方式，体验了这两种方法的效果。这节课的代码已经放到了我的 GitHub 上。接下来我们通过一张表格，对这两种方式进行对比和总结。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/13/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/13/4.png" alt=""></a></p><p>这两种方式各有所长，于是开源社区便研发了一些协议转换工具，比如 mcp-proxy ，允许将 stdio 模式的服务器转换为 SSE 模式运行。例如，用户可以通过 mcp-proxy 在 ClaudeDesktop 中使用 stdio 服务器，而无需重新实现为 SSE 模式。</p><p>最后提醒一下，MCP 毕竟是一个刚出现了半年的新东西，虽然在社区引起了一些反响，也有很多 IDE 进行了接入，但还远远没有发展到能和 Agent 二分天下的时候。因此我为你讲解这个技术就是为了追新，让你有一个知识储备，以不变应万变。基本就学到这个程度就可以了，无需太深究，否则一旦后面 MCP 没发展起来，现在过度深究就是走弯路了。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你认为 Roo Code 等 IDE 用的是 Stdio 还是 SSE 方式？</p><p>欢迎你在留言区展示你的思考结果，我们一起探讨。如果你觉得这节课的内容对你有帮助的话，也欢迎你分享给其他朋友，我们下节课再见！</p>`,78)])])}const g=a(t,[["render",p]]);export{u as __pageData,g as default};
